68	    /**
69	     * Write-only, non-persistent acknowledgement that this owner deliberately shares a
70	     * household with an existing owner. When {@code true}, creation is allowed even if
71	     * another owner already has the same lastName and address.
72	     */
73	    @Transient
74	    private boolean sharesHousehold;
75	
76	    /**
77	     * Read-only, non-persistent count of the owners that share this owner's {@code householdId}
78	     * (including this owner), populated by the service when an owner is loaded for presentation.
79	     * Zero when the owner belongs to no household. Used to derive the membership tier.
