251	    @Override
252	    @Transactional
253	    public void saveOwner(Owner owner) throws DataAccessException {
254	        if (owner.getTelephone() != null) {
255	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
256	        }
257	        if (owner.getEmail() != null) {
258	            owner.setEmail(normalizeEmail(owner.getEmail()));
259	        }
260	        if (owner.getAddress() != null) {
261	            owner.setAddress(normalizeAddress(owner.getAddress()));
262	        }
263	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
264	        owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
265	        if (owner.getCustomerCode() == null) {
266	            owner.setCustomerCode(generateCustomerCode(owner));
267	        }
268	        boolean creating = owner.isNew();
269	        if (creating) {
270	            owner.setNamesakeCount(countNamesakes(owner));
271	            assertDailyCapacity(owner);
272	            assertCityCapacity(owner);
273	        }
274	        List<Owner> household = findHouseholdMembers(owner);
275	        assignHousehold(owner, household);
276	        assertIdentityUnique(owner);
277	        ownerRepository.save(owner);
278	        populateHouseholdSize(owner);
279	        if (creating) {
280	            AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
281	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
282	                owner.getMembershipLevel());
283	        }
284	    }
285	
286	    /**
287	     * Build a {@code customerCode} formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
288	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three
289	     * letters of {@code lastName}, and NNNN is a per-city 4-digit zero-padded sequence equal to
290	     * one more than the number of owners already in that city.
291	     */
292	    private String generateCustomerCode(Owner owner) {
293	        String cityPrefix = prefix3(owner.getCity());
294	        String lastNamePrefix = prefix3(owner.getLastName());
295	        long sequence = countOwnersInCity(owner.getCity()) + 1L;
296	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
297	    }
298	
299	    private static String prefix3(String value) {
300	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
301	    }
302	
303	    /** Maximum number of owners permitted in a single city. */
304	    private static final long CITY_OWNER_LIMIT = 50L;
305	
306	    /**
307	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
308	     * more owners, so no city can grow beyond the capacity limit.
309	     *
310	     * @throws CityOwnerLimitException if the owner's city is already at capacity
311	     */
312	    private void assertCityCapacity(Owner owner) {
313	        if (owner.getCity() == null) {
314	            return;
315	        }
316	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
317	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
318	        }
319	    }
320	
321	    /**
322	     * Rolls {@code date} forward to the next business day when it falls on a weekend: a Saturday or
323	     * Sunday becomes the following Monday. Business days (Monday to Friday) are returned unchanged.
324	     */
325	    private static LocalDate rollToBusinessDay(LocalDate date) {
326	        switch (date.getDayOfWeek()) {
327	            case SATURDAY:
328	                return date.plusDays(2);
329	            case SUNDAY:
330	                return date.plusDays(1);
331	            default:
332	                return date;
333	        }
334	    }
335	
336	    /** Maximum number of owners permitted to be registered on a single day. */
337	    private static final long DAILY_OWNER_LIMIT = 100L;
338	
339	    /** More than this many owners registered on a single day raises the bulk-signup warning. */
340	    private static final long BULK_SIGNUP_THRESHOLD = 80L;
341	
342	    /**
343	     * Reports whether more than {@link #BULK_SIGNUP_THRESHOLD} owners have already been registered
344	     * today, reusing the same daily accumulation as the per-day create limit ({@link
345	     * #assertDailyCapacity}).
346	     */
347	    @Override
348	    @Transactional(readOnly = true)
349	    public boolean isBulkSignupWarningActive() throws DataAccessException {
350	        return countOwnersRegisteredOn(LocalDate.now()) > BULK_SIGNUP_THRESHOLD;
351	    }
352	
353	    /**
354	     * Rejects creating {@code owner} when its {@code registrationDate} (defaulted to today for a new
355	     * owner) already has {@link #DAILY_OWNER_LIMIT} or more owners registered, so no more than that
356	     * many owners can be created on any single day.
357	     *
358	     * @throws DailyOwnerLimitException if the owner's registration day is already at capacity
359	     */
360	    private void assertDailyCapacity(Owner owner) {
361	        LocalDate date = owner.getRegistrationDate();
362	        if (date == null) {
363	            return;
364	        }
365	        if (countOwnersRegisteredOn(date) >= DAILY_OWNER_LIMIT) {
366	            throw new DailyOwnerLimitException(date, DAILY_OWNER_LIMIT);
367	        }
368	    }
369	
370	    private long countOwnersRegisteredOn(LocalDate date) {
371	        return ownerRepository.findAll().stream()
372	                .filter(existing -> date.equals(existing.getRegistrationDate()))
373	                .count();
374	    }
375	
376	    private long countOwnersInCity(String city) {
377	        String normalized = normalizeHouseholdValue(city);
378	        return ownerRepository.findAll().stream()
379	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
380	                .count();
381	    }
382	
383	    /**
384	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
385	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
386	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
387	     * that already existed before this create.
388	     */
389	    private int countNamesakes(Owner owner) {
390	        String firstName = normalizeHouseholdValue(owner.getFirstName());
391	        String lastName = normalizeHouseholdValue(owner.getLastName());
392	        int count = 0;
393	        for (Owner existing : ownerRepository.findAll()) {
394	            if (!existing.getId().equals(owner.getId())
395	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
396	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
397	                count++;
398	            }
399	        }
400	        return count;
401	    }
402	
403	    private static String normalizeEmail(String email) {
404	        return email == null ? null : email.toLowerCase(Locale.ROOT);
405	    }
406	
407	    /** Common street-type abbreviations expanded during address normalization. */
408	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
409	        "ST", "STREET",
410	        "RD", "ROAD",
411	        "AVE", "AVENUE");
412	
413	    /**
414	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
415	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
416	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
417	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
418	     * form.
419	     */
420	    private static String normalizeAddress(String address) {
421	        if (address == null) {
422	            return null;
423	        }
424	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
425	        if (collapsed.isEmpty()) {
426	            return "";
427	        }
428	        String[] tokens = collapsed.split(" ");
429	        StringBuilder sb = new StringBuilder(collapsed.length());
430	        for (int i = 0; i < tokens.length; i++) {
431	            if (i > 0) {
432	                sb.append(' ');
433	            }
434	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
435	        }
436	        return sb.toString();
437	    }
438	
439	    private static String normalizeTelephone(String telephone) {
440	        return telephone == null ? null : E164Telephone.toE164(telephone);
441	    }
442	
443	    /**
444	     * Rejects saving {@code owner} when its whole {@link Owner#getIdentityKey() identity key} equals
445	     * that of another owner. This single check consolidates the former separate telephone, email and
446	     * household duplicate rules: because the normalized telephone is part of the key, two members of
447	     * the same household (same {@code householdId}) with different telephones have different keys and
448	     * are both allowed — only an exact full-key match is a duplicate.
449	     *
450	     * @throws DuplicateIdentityException if another owner already has the same identity key
451	     */
452	    private void assertIdentityUnique(Owner owner) {
453	        String identityKey = owner.getIdentityKey();
454	        for (Owner existing : ownerRepository.findAll()) {
455	            if (!existing.getId().equals(owner.getId()) && identityKey.equals(existing.getIdentityKey())) {
456	                throw new DuplicateIdentityException(identityKey);
457	            }
458	        }
459	    }
460	
461	    /**
462	     * Returns the existing owners that share both {@code lastName} (compared case-insensitively with
463	     * collapsed whitespace) and the normalized {@code address} with a new {@code owner} — i.e. the
464	     * members of the household it would join. Returns an empty list for an update to an existing
465	     * owner or when either household value is blank, so household rules only apply to genuine new
466	     * members.
467	     */
468	    private List<Owner> findHouseholdMembers(Owner owner) {
469	        if (!owner.isNew()) {
470	            return List.of();
471	        }
472	        String lastName = normalizeHouseholdValue(owner.getLastName());
473	        String address = normalizeHouseholdAddress(owner.getAddress());
474	        if (lastName.isEmpty() || address.isEmpty()) {
475	            return List.of();
476	        }
477	        List<Owner> household = new ArrayList<>();
478	        for (Owner existing : ownerRepository.findAll()) {
479	            if (!existing.getId().equals(owner.getId())
480	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))
481	                    && address.equals(normalizeHouseholdAddress(existing.getAddress()))) {
482	                household.add(existing);
483	            }
484	        }
485	        return household;
486	    }
487	
488	    /**
489	     * Assigns household membership when {@code owner} joins a non-empty {@code household}: the new
490	     * owner and every matching existing member that lacks one are given the same stable
491	     * {@code householdId}, and any updated existing members are persisted. No-op when the household
492	     * is empty.
493	     */
494	    private void assignHousehold(Owner owner, List<Owner> household) {
495	        if (household.isEmpty()) {
496	            return;
497	        }
498	        String householdId = resolveHouseholdId(owner, household);
499	        owner.setHouseholdId(householdId);
500	        for (Owner existing : household) {
501	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
502	                existing.setHouseholdId(householdId);
503	                ownerRepository.save(existing);
504	            }
505	        }
506	    }
507	
508	    /**
509	     * Stamps {@code owner} with the number of owners sharing its {@code householdId} (see {@link
510	     * Owner#getHouseholdSize()}), so presentation code can derive the membership tier without
511	     * reaching into the data store. A {@code null} owner or one without a household id is left at
512	     * size 0.
513	     */
514	    private void populateHouseholdSize(Owner owner) {
515	        if (owner == null) {
516	            return;
517	        }
518	        String householdId = owner.getHouseholdId();
519	        if (householdId == null || householdId.isBlank()) {
520	            owner.setHouseholdSize(0);
521	            return;
522	        }
523	        int count = 0;
524	        for (Owner existing : ownerRepository.findAll()) {
525	            if (householdId.equals(existing.getHouseholdId())) {
526	                count++;
527	            }
528	        }
529	        owner.setHouseholdSize(count);
530	    }
531	
532	    /**
533	     * Stamps every owner in {@code owners} with its household size in a single pass over the data
534	     * store, so a list/page of owners is counted without a per-owner query.
535	     *
536	     * @see #populateHouseholdSize(Owner)
537	     */
538	    private void populateHouseholdSizes(Collection<Owner> owners) {
539	        if (owners.isEmpty()) {
540	            return;
541	        }
542	        Map<String, Integer> sizes = new HashMap<>();
543	        for (Owner existing : ownerRepository.findAll()) {
544	            String householdId = existing.getHouseholdId();
545	            if (householdId != null && !householdId.isBlank()) {
546	                sizes.merge(householdId, 1, Integer::sum);
547	            }
548	        }
549	        for (Owner owner : owners) {
550	            String householdId = owner.getHouseholdId();
551	            owner.setHouseholdSize(householdId == null ? 0 : sizes.getOrDefault(householdId, 0));
552	        }
553	    }
554	
555	    /**
556	     * Returns the {@code householdId} shared by a household: the first non-blank identifier already
557	     * carried by an existing member, or otherwise a freshly derived stable identifier for the
558	     * joining {@code owner}'s normalized lastName and address.
559	     */
560	    private String resolveHouseholdId(Owner owner, List<Owner> household) {
561	        for (Owner existing : household) {
562	            if (existing.getHouseholdId() != null && !existing.getHouseholdId().isBlank()) {
563	                return existing.getHouseholdId();
564	            }
565	        }
566	        return generateHouseholdId(normalizeHouseholdValue(owner.getLastName()),
567	            normalizeHouseholdAddress(owner.getAddress()));
568	    }
569	
570	    /**
571	     * Derives a stable {@code householdId} formatted {@code 'HH-<12 upper-hex>'} from the SHA-256
572	     * digest of the normalized {@code lastName} and {@code address}, so all owners in the same
573	     * household deterministically share the same identifier.
574	     */
575	    private static String generateHouseholdId(String lastName, String address) {
576	        try {
577	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
578	            byte[] hash = digest.digest((lastName + "\u0000" + address).getBytes(StandardCharsets.UTF_8));
579	            StringBuilder sb = new StringBuilder();
580	            for (int i = 0; i < 6; i++) {
581	                sb.append(String.format("%02X", hash[i]));
582	            }
583	            return "HH-" + sb;
584	        } catch (NoSuchAlgorithmException e) {
585	            throw new IllegalStateException("SHA-256 not available", e);
586	        }
587	    }
588	
589	    /**
590	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
591	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
592	     */
593	    private static String normalizeHouseholdValue(String value) {
594	        if (value == null) {
595	            return "";
596	        }
597	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
598	    }
599	
600	    /**
601	     * Household comparison value for an address: the canonical {@link #normalizeAddress(String)}
602	     * form (never {@code null}), so duplicate detection and the shared household id compare
603	     * addresses using the same normalized representation that is stored and returned.
604	     */
605	    private static String normalizeHouseholdAddress(String address) {
606	        String normalized = normalizeAddress(address);
607	        return normalized == null ? "" : normalized;
608	    }
609	
610	    @Override
611	    @Transactional(readOnly = true)
612	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
613	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
614	        populateHouseholdSizes(owners);
615	        return owners;
616	    }
617	
618	    @Override
619	    @Transactional(readOnly = true)
620	    public Collection<Visit> findVisitsByPetId(int petId) {
621	        return visitRepository.findByPetId(petId);
622	    }
623	
624	    @Override
625	    @Transactional(readOnly = true)
626	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
627	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
628	    }
629	
630	    private <T> T findEntityById(Supplier<T> supplier) {
631	        try {
632	            return supplier.get();
633	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
634	            // Just ignore not found exceptions for Jdbc/Jpa realization
635	            return null;
636	        }
637	    }
638	
639	}
